  smithy: { s1: { rect: 3, side: 1 }, s2: { keep: 0.5, L: 1, T: 1, back: 1, extend: 1.5, long: 1 }, s3: { keep: 0.5, L: 2, T: 2, U: 1, extend: 1, long: 1 },
    storey: { s2: 0, s3: 0 }, extras: { outshut: [0, 0.4, 0.3] } },
