  farm: { s1: { rect: 1 }, s2: { keep: 1, long: 1, extend: 1 }, s3: { keep: 1, extend: 1, back: 1, T: 1 }, storey: { s2: 0, s3: 0 }, extras: { outshut: [0, 0.3, 0.3] } },
