  const P = plan.persona, d = c.decor === 'd3' ? 3 : 2;
  const q = d === 3 ? K.per10[1] + (K.per10[2] - K.per10[1]) * (0.3 + 0.7 * (P.clutter || 0.5)) : K.per10[0] + (K.per10[1] - K.per10[0]) * (0.5 + 0.5 * (P.clutter || 0.5));
