      for (const s of near(x, z, 0.2)) if (s.y0 < f.st + 1.6 && s.y1 > f.st + 0.3 && ptDist(s.b, x, z) < (s.role === 'pole' ? 0.12 : 0.03)) { blocked = true; break; }
      if (!blocked) cells.set(k, { i, j, x, z, st: f.st });
