        const en = o.h[0] * Math.abs(o.a[0][0] * f.nx + o.a[0][2] * f.nz) + o.h[1] * Math.abs(o.a[1][0] * f.nx + o.a[1][2] * f.nz) + o.h[2] * Math.abs(o.a[2][0] * f.nx + o.a[2][2] * f.nz);
