      spots.sort((a, b) => (Math.hypot(a.x - px, a.z - pz) - (a.centered === 2 ? 0.4 : 0)) - (Math.hypot(b.x - px, b.z - pz) - (b.centered === 2 ? 0.4 : 0)));
