const BIOMES = ['Meadows', 'Black Forest', 'Swamp', 'Mountain', 'Plains', 'Mistlands', 'Ashlands', 'Deep North'];
const tierOf = b => Math.max(0, typeof b === 'number' ? b : BIOMES.indexOf(b || 'Meadows'));
