  const H = (P && P.hobby) || { food: 0.5, collect: 0.3, crafts: 0.3, plants: 0.3, games: 0.2, maps: 0.1 };
  for (const [h, v] of Object.entries(H)) for (const [t, w] of Object.entries(R_[h] || {})) out[t] = (out[t] || 0) + v * w;
