      if (!t || !/[A-Za-z]/.test(t)) fails.push({ code: 'empty-armor', msg: 'armor stand with nothing on it', at: [p.x, p.y, p.z] });
      else { counts.armorDressed++; counts.outfits[t] = (counts.outfits[t] || 0) + 1; }
      continue;
