  const village = opts.green != null ? +opts.green : VILLAGE_GREEN[0] + vR() * (VILLAGE_GREEN[1] - VILLAGE_GREEN[0]);
  const lean = LEAN[ctx.cultureKey] || (ctx.biome === 'Ashlands' ? LEAN.ashlands : {});
