      const cx = (o.x0 + o.x1) / 2, cz = (o.z0 + o.z1) / 2;
      const pts = [[o.x0 - d, cz + (R() - 0.5)], [o.x1 + d, cz + (R() - 0.5)], [cx + (R() - 0.5), o.z0 - d], [cx + (R() - 0.5), o.z1 + d]];
