      if (up && s > 0) room.keep.push(...(up.run || [up.hole]).map(cellRect), cellRect(up.land));
      if (next) room.keep.push(cellRect(next.stand), ...(next.run || [next.hole]).map(cellRect));
      if (flue && s > 0) room.keep.push(flue);
