    const gone = parts.filter(overDeck);
    const underGone = p => p.role === 'trim' && gone.some(e => Math.hypot(e.x - p.x, e.z - p.z) < 1.5 && p.y < e.y + 0.3 && p.y > e.y - 1.6);
